# Code generated by Claude
"""
The bench rectangle stance selection in the live pipeline: the plan "navigate to the beaker, pick it up, navigate to the hotplate, place it" runs to success with ONE stance chosen from the bench rectangle
(BENCH_RECT_CFG["rectangle"], measured by experiments/bench_rectangle_measure.py) and a NULL second navigation step, recorded and replayed.

    MUJOCO_GL=egl python experiments/stance_select_pipeline_test.py [--plumbing]

--plumbing: a hand-set rectangle (forward 0.39 to 0.48 m, 0.10 m right to 0.35 m left), NOT the measured one, whose centred spot passes the full check: it tests the plumbing (one stance, the null second navigation
step, the staging at the chosen spot, record and replay). With the measured rectangle (BENCH_RECT_CFG["rectangle"]) the selection finds no spot that passes the full check today (see the Stage 5 report): the
test then reports the selection and fails at its first check.

Steps: (1) the selection: the rectangle, the plan's runs, the full check of the chosen spot (its own simulation, freed before the next); (2) the pipeline run on the chosen stance; (3) the replay.
Reports the chosen stance next to TASK_CFG's, the candidates and the full check's verdicts, the time of the selection and the staging's arrival errors.
"""

import gc
import json
import os
import shutil
import sys
import tempfile
import time
from pathlib import Path

PROJECT_ROOT = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(PROJECT_ROOT))
sys.path.insert(0, str(PROJECT_ROOT / "experiments"))
if not os.environ.get("DISPLAY"):
    os.environ.setdefault("MUJOCO_GL", "egl")

import numpy as np  # noqa: E402

from src.bench_rectangle import load_maps  # noqa: E402
from src.episode_runner import run_episode  # noqa: E402
from src.full_check import FullCheck, task_points  # noqa: E402
from src.mpvi_pipeline import make_pipeline_task  # noqa: E402
from src.mpvi_postprocess import make_stored_labeler, postprocess  # noqa: E402
from src.replay import replay_run  # noqa: E402
from src.stance_select import select_bench_stance  # noqa: E402
from src.task_beaker_hotplate import load_task  # noqa: E402
from src.task_config import BENCH_RECT_CFG, TASK_CFG  # noqa: E402
from src.world_model import StaticTaskSource, WorldModel  # noqa: E402
from stance_select_test import LABELS4, PLAN4  # noqa: E402

results = []


def check(name, ok, detail=""):
    results.append(bool(ok))
    print(f"  {'PASS' if ok else 'FAIL'}  {name}  {detail}", flush=True)


PLUMBING_RECT = {"forward_near": 0.39, "forward_far": 0.48, "right": -0.10, "left": 0.35}


def main(plumbing=False):
    cfg = {**BENCH_RECT_CFG, "mode": "bench_rectangle", **({"rectangle": PLUMBING_RECT} if plumbing else {})}
    if cfg["rectangle"] is None:
        print("the rectangle is not measured yet")
        return False
    labeler = make_stored_labeler(LABELS4)
    tagged = postprocess(PLAN4, labeler, False)
    world = WorldModel([StaticTaskSource()])
    world.refresh(0.0)
    print("1. the selection", flush=True)
    t0 = time.perf_counter()
    fc = FullCheck(maps=load_maps(PROJECT_ROOT / "data" / "reach_map"))
    sel = select_bench_stance(tagged, world, TASK_CFG, cfg, full_check=fc, points=task_points(fc.model, fc.scene_data))
    t_sel = time.perf_counter() - t0
    del fc
    gc.collect()
    rep = sel["report"]
    ch = rep.get("chosen")
    print(f"  rectangle {rep['rectangle']}\n  runs {[(r['nav'], r['steps'], r['fits']) for r in rep['runs']]}\n  candidates {[(np.round(c['xy'], 3).tolist(), c['shift'], c.get('full_check_ok'), c.get('seconds')) for c in rep['candidates']]}\n"
          f"  chosen {ch}\n  TASK_CFG's stance: xy {TASK_CFG['staging_xy']}, yaw {TASK_CFG['staging_yaw']:.3f}, pedestal {TASK_CFG['pedestal_q']}\n  selection time (the full check's simulation load included): {t_sel:.1f} s; notes {rep['notes']}")
    check("a stance was chosen and passed the full check", sel["ok"] and rep["candidates"][-1].get("full_check_ok"), f"{rep['notes']}")
    check("one run, the second navigation step is null", len(rep["runs"]) == 1 and rep.get("null_nav") == [2], f"{rep.get('null_nav')}")
    if not sel["ok"]:
        return False
    d = float(np.hypot(*(np.array(ch["xy"]) - np.array(TASK_CFG["staging_xy"]))))
    print(f"  the chosen spot is {1000 * d:.0f} mm from TASK_CFG's", flush=True)

    print("\n2. the pipeline on the chosen stance", flush=True)
    sim = load_task(cameras=True)
    task = make_pipeline_task(PLAN4, task_cfg=sel["task_cfg"], labeler=labeler)
    out = Path(tempfile.mkdtemp(prefix="stance_select_"))
    s = run_episode(task, sim.model, sim.data, out_dir=out / "episode", record_dir=out / "recording")
    state = task["pipeline"]["orchestrator"]["state"]
    print(f"  outcome {s['outcome']}; plan failure {state['failure']}; status {state['status']}")
    check("the episode outcome is SUCCESS", s["outcome"] == "SUCCESS", s["outcome"])
    check("the plan finished, every segment done (the second navigation step too)", state["finished"] and all(x == "done" for x in state["status"]) and len(state["status"]) == 4, f"{state['status']}")
    a = s.get("arrival_at_end_of_drive") or {}
    h = s.get("base_pose_error_at_handoff") or {}
    print(f"  arrival at the approach spot {a}; handoff pose error {h}")
    check("the staging arrived within 1 cm and 1 degree at the chosen stance", bool(a) and a["pos_err_mm"] <= 10.0 and abs(a["yaw_err_deg"]) <= 1.0 and h["pos_err_mm"] <= 10.0 and abs(h["yaw_err_deg"]) <= 1.0)
    ok, diag = task["check_success"](sim.model, sim.data)
    check("the beaker stands on the hotplate", ok, str({k: diag[k]["ok"] for k in diag if isinstance(diag[k], dict) and "ok" in diag[k]}))
    print("\n3. the replay", flush=True)
    del sim, task
    gc.collect()
    r = replay_run(out / "recording", video="none", quiet=True)
    check("the replay is bit-identical", r["ok"], f"{r['ticks']} ticks, mismatch {r['mismatch']}")
    (out / "selection.json").write_text(json.dumps(rep, indent=1, default=str))
    keep = PROJECT_ROOT / "data" / "stance_select_report.json"
    tmp = keep.with_suffix(".tmp")
    tmp.write_text(json.dumps({"selection": rep, "select_seconds": t_sel, "arrival": a, "handoff": h, "taskcfg_stance": {"xy": TASK_CFG["staging_xy"], "yaw": TASK_CFG["staging_yaw"], "pedestal_q": TASK_CFG["pedestal_q"]}}, indent=1, default=str))
    tmp.replace(keep)
    shutil.rmtree(out, ignore_errors=True)
    print(f"\n{sum(results)}/{len(results)} checks passed")
    return all(results)


if __name__ == "__main__":
    sys.exit(0 if main("--plumbing" in sys.argv) else 1)
